<template><main class="hh-page surgery-agenda"><router-link to="/unidad-quirurgica" class="hh-back-link d-inline-flex align-items-center mb-3"><i class="ph ph-arrow-left me-1"></i>Volver a unidad quirúrgica</router-link><section class="agenda-hero"><div><span>PLANEACIÓN QUIRÚRGICA</span><h1>{{historyMode?'Historial de cirugías':'Agenda quirúrgica'}}</h1><p>{{historyMode?'Consulte procedimientos realizados, cancelados y programados.':'Organice la ocupación de quirófanos por fecha y horario.'}}</p></div><router-link to="/unidad-quirurgica/programar" class="btn btn-light text-primary"><i class="ph ph-plus me-1"></i>Programar cirugía</router-link></section><section class="filters mt-4"><form class="row g-3" @submit.prevent="load"><div class="col-md-4"><label class="form-label">Quirófano</label><select v-model="form.roomId" class="form-select" :required="!historyMode"><option value="">{{historyMode?'Todos':'Seleccione'}}</option><option v-for="item in rooms" :key="item.id" :value="item.id">{{item.nombre_quirofano}}</option></select></div><div class="col-md-3"><label class="form-label">Desde</label><input v-model="form.desde" type="date" class="form-control"></div><div class="col-md-3"><label class="form-label">Hasta</label><input v-model="form.hasta" type="date" class="form-control"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100" :disabled="loading">Consultar</button></div></form></section><div v-if="error" class="alert alert-danger mt-3">{{error}}</div><section class="agenda-results mt-4"><header><div><small>RESULTADOS</small><h2>{{rows.length}} procedimientos</h2></div><label><i class="ph ph-magnifying-glass"></i><input v-model="search" placeholder="Paciente o procedimiento"></label></header><div v-if="loading" class="text-center py-5"><span class="spinner-border text-primary"></span></div><div v-else-if="!filtered.length" class="empty"><i class="ph ph-calendar-x"></i><h3>Sin cirugías</h3><p>No existen procedimientos en el rango consultado.</p></div><div v-else class="agenda-list"><router-link v-for="item in filtered" :key="item.id_procedimiento||item.id" :to="`/unidad-quirurgica/cirugias/${item.id_procedimiento||item.id}`"><time><strong>{{formatDate(item.fecha)}}</strong><span>{{String(item.hora_inicio).slice(0,5)}} – {{String(item.hora_fin).slice(0,5)}}</span></time><div class="room"><small>QUIRÓFANO</small><strong>{{item.quirofano||item.nombre_quirofano||roomName(item.id_quirofano)}}</strong></div><div class="procedure"><strong>{{item.procedimiento||item.servicio||'Procedimiento quirúrgico'}}</strong><small>{{item.paciente}} · {{item.cirujano}}</small></div><span class="status">{{item.estado_procedimiento||item.estado_programacion}}</span><i class="ph ph-caret-right"></i></router-link></div></section></main></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{obtenerMensajeError}from'@/services/api';import{consultarAgendaQuirofano,consultarHistorialQuirofanos,listarQuirofanos}from'@/services/unidadQuirurgica';const route=useRoute(),historyMode=computed(()=>route.path.endsWith('/historial')),rooms=ref([]),rows=ref([]),loading=ref(false),error=ref(''),search=ref(''),now=new Date(),form=reactive({roomId:'',desde:new Date(now.getFullYear(),now.getMonth(),1).toISOString().slice(0,10),hasta:new Date(now.getFullYear(),now.getMonth()+1,0).toISOString().slice(0,10)}),array=v=>Array.isArray(v)?v:Array.isArray(v?.data)?v.data:[],roomName=id=>rooms.value.find(x=>Number(x.id)===Number(id))?.nombre_quirofano||`Quirófano ${id}`,formatDate=v=>v?new Intl.DateTimeFormat('es-CO',{dateStyle:'medium'}).format(new Date(`${v}T00:00:00`)):'Sin fecha',filtered=computed(()=>{const t=search.value.toLowerCase();return rows.value.filter(x=>[x.paciente,x.procedimiento,x.servicio,x.cirujano].join(' ').toLowerCase().includes(t))});function flatten(v){const a=array(v);return a.flatMap(x=>Array.isArray(x.cirugias)?x.cirugias.map(c=>({...c,id_quirofano:c.id_quirofano||x.id_quirofano,quirofano:c.quirofano||x.quirofano})):x)}async function load(){if(!historyMode.value&&!form.roomId)return;loading.value=true;error.value='';try{const r=historyMode.value?await consultarHistorialQuirofanos({...(form.roomId?{id_quirofano:form.roomId}:{}),desde:form.desde,hasta:form.hasta}):await consultarAgendaQuirofano(form.roomId,{desde:form.desde,hasta:form.hasta});rows.value=flatten(r)}catch(e){error.value=obtenerMensajeError(e)}finally{loading.value=false}}onMounted(async()=>{rooms.value=array(await listarQuirofanos().catch(()=>[]));if(!historyMode.value&&rooms.value.length)form.roomId=rooms.value[0].id;await load()})</script>
<style scoped>.agenda-hero{display:flex;align-items:center;justify-content:space-between;padding:1.4rem 1.5rem;border-radius:1rem;background:linear-gradient(120deg,#124b76,#1187ac);color:#fff}.agenda-hero span,.agenda-results>header small{font-size:.68rem;font-weight:800;letter-spacing:.08em}.agenda-hero h1{margin:.2rem 0;font-size:1.55rem}.agenda-hero p{margin:0;opacity:.82}.filters,.agenda-results{overflow:hidden;border:1px solid #dfe7ee;border-radius:1rem;background:#fff;box-shadow:0 9px 28px rgba(25,63,95,.06)}.filters{padding:1rem}.agenda-results>header{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.2rem;border-bottom:1px solid #e3e9ef;background:#fbfcfe}.agenda-results h2{margin:.1rem 0;font-size:1.05rem}.agenda-results>header label{display:flex;align-items:center;gap:.4rem;padding:.4rem .6rem;border:1px solid #dfe6ec;border-radius:.55rem;background:#fff}.agenda-results>header input{border:0;outline:0}.agenda-list{display:grid}.agenda-list>a{display:grid;grid-template-columns:150px 150px minmax(240px,1fr) auto 20px;align-items:center;gap:.8rem;padding:.8rem 1rem;border-bottom:1px solid #e8edf1;color:#425267}.agenda-list time strong,.agenda-list time span,.agenda-list small,.agenda-list .procedure strong{display:block}.agenda-list time strong,.agenda-list .procedure strong,.agenda-list .room strong{font-size:.76rem}.agenda-list time span,.agenda-list small{color:#7d8b9a}.status{padding:.28rem .5rem;border-radius:20px;background:#e8f4fc;color:#247bad;font-size:.65rem}.empty{text-align:center;padding:4rem;color:#718096}.empty i{font-size:2.8rem;color:#abc1d0}.empty h3{margin:.6rem 0 .2rem;font-size:1rem}@media(max-width:800px){.agenda-list>a{grid-template-columns:1fr auto}.agenda-list .room,.agenda-list .procedure{grid-column:1/-1}.agenda-hero{align-items:flex-start;flex-direction:column;gap:1rem}}</style>
